import {renderChickenLab} from './chicken-lab-view.js';
import {t,getLocale} from './locales.js';import {el} from './dom.js';
import {CHICKEN} from './chicken-config.js';
/** @typedef {import('./chicken-view-types.js').YardSnapshot & {storeFeedG?:number,tankWaterL?:number,coins?:number,feedCapacityG?:number,waterCapacityL?:number,lab?:ReturnType<typeof import('./chicken-lab.js').chickenLab>,comfort?:number,comfortReason?:string,cleanWait?:number,eggInventory?:number}} CareSnapshot */
/** @type {CareSnapshot|null} */let renderedSnapshot=null;let renderedLocale='';
/** @param {CareSnapshot} snapshot @param {string} selected */
export function renderChickenPanel(snapshot,selected){
 const panel=el('chicken-panel');panel.hidden=!selected;if(!selected)return;el('chicken-heading').textContent=t(selected==='clean'?'cleanStation':selected);if(renderedSnapshot===snapshot&&renderedLocale===getLocale())return;const stats=el('chicken-status');stats.replaceChildren();
 for(const [key,value]of [['hensCount',String(snapshot.hens?.length||0)],['feedStock',Math.round(snapshot.feedG||0)+' g'],['drinkStock',(snapshot.waterL||0).toFixed(1)+' L'],['cleanliness',Math.round(snapshot.cleanliness??100)+'%'],['eggsReady',String(snapshot.pendingEggs)],['comfort',Math.round((snapshot.comfort||0)*100)+'%']]){const cell=document.createElement('div'),label=document.createElement('dt'),number=document.createElement('dd');label.textContent=t(key);number.textContent=value;cell.append(label,number);stats.append(cell);}
 const labOpen=!!document.querySelector('#chicken-lab[open]'),whyOpen=!!document.querySelector('#chicken-why[open]'),actions=el('chicken-actions');actions.replaceChildren();
 const descriptions=[['feed','feedHens',(snapshot.feedG||0)>=(snapshot.feedCapacityG||2000)?'feederFull':(snapshot.storeFeedG||0)<=0?'noChickenFeed':'','feedHint'],['water','waterHens',(snapshot.waterL||0)>=(snapshot.waterCapacityL||6)?'drinkerFull':(snapshot.tankWaterL||0)<=0?'noWater':'','drinkHint'],['clean','cleanCoop',(snapshot.cleanliness??100)>=99.999?'alreadyClean':(snapshot.cleanWait||0)>0?'cleanCooldown':(snapshot.coins||0)<CHICKEN.cleanPrice?'noCoins':'','cleanHint'],['collect','collectEggs',snapshot.pendingEggs<=0?'noEggs':(snapshot.eggInventory||0)+snapshot.pendingEggs>CHICKEN.eggInventoryMax?'eggInventoryFull':'','collectHint']];
 for(const [id,label,reason,hint]of descriptions){const row=document.createElement('div');row.className='chicken-action';const b=document.createElement('button');b.type='button';b.id='chicken-'+id;b.className='action-button';b.dataset.chickenAction=id;b.textContent=t(label);b.disabled=!!reason;b.title=t(reason||hint);const text=document.createElement('p');text.id='chicken-reason-'+id;text.textContent=t(reason||hint);b.setAttribute('aria-describedby',text.id);b.addEventListener('click',()=>document.dispatchEvent(new CustomEvent('chickenaction',{detail:id})));row.append(b,text);actions.append(row);}
 const why=document.createElement('details'),summary=document.createElement('summary'),reason=document.createElement('p');why.id='chicken-why';why.open=whyOpen;summary.textContent=t('whyChicken');reason.textContent=t(snapshot.comfortReason||'chickenNotReady');why.append(summary,reason);actions.append(why,renderChickenLab(snapshot.lab,labOpen));renderedSnapshot=snapshot;renderedLocale=getLocale();
}
